D=Path('docs'); F=[]
def add(id,area,sev,title,file,needle,wrong,proof,fix,status='Confirmed by source inspection'):
 lines=Path(file).read_text().splitlines(); line=next((n for n,l in enumerate(lines,1) if needle in l),None)
 assert line,(file,needle)
 F.append(dict(id=id,area=area,severity=sev,title=title,source=f'{file}:{line}',wrong=wrong,evidence=proof,fix=fix,status=status))
add('D01','D Authorization','Critical','Profile mass assignment permits system administrator escalation','backend/src/controllers/auth.controller.ts','data: req.body','The validator parses but discards the sanitized result; updateMe passes the original body to Prisma, including systemRole and nested relations.','Authenticated PATCH /api/auth/me with {"name":"Audit","systemRole":"SUPER_ADMIN"} passes updateMeSchema (unknown keys are stripped only in the returned value) and reaches user.update unchanged. No live account modified.','Assign parsed data back to req.body and allowlist profile fields in the controller; regression-test systemRole, clerkId and nested membership writes.')
add('E01','E Input handling','Critical','Authenticated arbitrary code execution on API host','backend/src/controllers/snippet.controller.ts','const child = spawn','Submitted code runs native interpreters with the API OS identity, filesystem/network access, inherited secrets and attacker-controlled environment. A timeout is not isolation.','Any signed-in user can POST /api/snippets/execute with JavaScript console.log(process.getuid?.()) or arbitrary fs/network calls; route has no workspace gate. Source establishes capability; dangerous execution was not performed.','Disable exposed execution until moved to isolated disposable workers with no application secrets, denied network, resource/process limits and tenant quotas.')
add('D02','D Authorization','Critical','Yjs room prefix authorizes the wrong document','backend/src/services/yjs.service.ts','let targetWorkspaceId = room.workspaceId','For document:ownWorkspace:victimDocument authentication checks the supplied workspace, while fetch/store use only victimDocument.','A member of A supplies room document:A:documentB. No comparison to documentB.workspaceId occurs. With a non-bypass RLS role the unscoped query fails instead (G01); with the supplied postgres setup this exposes B. Live exploit unverified.','Resolve canonical document workspace first; compare room workspace and require role; use tenant-scoped fetch/store and reject missing documents.')
add('D03','D Authorization','High','Socket.io room joins expose other workspaces','backend/src/socket/presence.handler.ts','socket.join(roomKey)','Any authenticated socket joins any workspace ID and receives presence and future room broadcasts without membership verification.','Emit workspace:join {workspaceId:otherId,userName:"Audit"}; only Zod validation precedes join.','Check membership using server identity before joining; evict on membership changes.')
add('D04','D Authorization','High','Kanban socket relays permit viewer and outsider spoofing','backend/src/socket/kanban.handler.ts',"socket.on('kanban:task-moved'",'All four Kanban input events relay client content to arbitrary workspace rooms without role or resource checks. These handlers do not persist database changes.','Emit task-created/updated/deleted/moved targeting another workspace; socket.to does not require sender room membership.','Accept authorized server mutations as canonical broadcasts; otherwise verify membership, editor role, resource ownership and bounded task schema.')
add('D05','D Authorization','High','Workspace owner can modify members in another workspace','backend/src/controllers/workspace.controller.ts','export async function updateMemberRole','Owner middleware checks URL workspace, but member update/delete uses memberId alone.','As owner of A PATCH /api/workspaces/A/members/memberB {role:"OWNER"}, or DELETE a non-owner memberB. WorkspaceMember has no RLS policy.','Use composite workspace and member filters and transactionally enforce owner invariants.')
add('D06','D Authorization','High','Creating a column has no board authorization','backend/src/controllers/task.controller.ts','export async function createColumn','Authenticated requests create columns on arbitrary boards; unlike update/delete there is no editor check.','POST /api/tasks/boards/otherBoard/columns {name:"Injected"}; Board/Column are not protected by the RLS migration.','Resolve board workspace and require editor before reading positions or creating columns.')
add('D07','D Authorization','High','Yjs viewers can write','backend/src/services/yjs.service.ts',"if (!member) throw",'Hocuspocus authentication accepts all membership roles and never marks viewers read-only.','Connect as a VIEWER and send a Yjs update; auth returns the same context as an editor. No role decision before storage.','Enforce server read-only connection state for viewers; test write attempts with raw protocol clients.')
add('D08','D Authorization','High','Cross-workspace document hierarchy can expose children','backend/src/controllers/document.controller.ts','parentId,','Document creation accepts any parentId; child includes do not filter workspace. The FK only enforces that a document exists.','Under the supplied bypass-RLS database role, editor A creates a document with parentId=documentB. Member B then reads children including A metadata/content in list nesting. Live DB reproduction unverified.','Require parent workspace match and enforce tenant relationships at database level; scope recursive reads.')
add('C01','C Authentication','High','Membership removal and suspension do not revoke collaboration access','backend/src/services/yjs.service.ts','async onAuthenticate','Authorization is checked at connection time only; no token expiry timer or role-change eviction is wired. Kill-switch/SCIM disconnect Socket.io, not Hocuspocus. isActive is not checked in REST/socket principal resolution.','Connect, remove/demote member or suspend tenant, then continue sending Yjs updates. Need authenticated integration fixture to verify connection lifetime.','Enforce active user/tenant and current authorization throughout session; close all collaboration transports on revocation and expire sessions.')
add('C02','C Authentication','Medium','Public GET reset clears cookies and redirects externally','frontend/src/app/api/auth/reset/route.ts','const redirectTo','A public GET performs logout-like cookie deletion and accepts absolute/protocol-relative redirect destinations.','GET /api/auth/reset?redirect=https://example.com yields an external redirect while expiring same-origin cookies. Can be triggered by top-level cross-site navigation.','Allowlist same-origin relative paths; use a protected POST for session changes and provider revocation.')
add('C03','C Authentication','Medium','Invites enumerate registered accounts and bypass acceptance','backend/src/controllers/workspace.controller.ts',"User not found with that email",'Workspace owners distinguish unregistered email, existing member and existing nonmember; invitation immediately inserts membership with no invitation/acceptance record.','Own any workspace, invite candidate emails and compare 404 vs success vs already-member error.','Use pending invitations with normalized email, opaque responses, expiry, consent and per-owner limits.')
add('C04','C Authentication','Medium','SCIM provisioned identities conflict with Clerk and global profile state','backend/src/routes/scim.routes.ts','clerkId: `scim:','SCIM email upsert creates a synthetic clerkId or edits an existing global user. Clerk sync upserts by real clerkId against unique email, without identity linking; isActive is global yet not enforced.','Provision new email via SCIM then sign in with that email via Clerk: unique email conflicts. Tenant token can change name/active/email on a shared user via its external identity.','Design explicit verified identity linking and tenant-local provisioning state; enforce deprovisioning on every transport without mutating unrelated tenant identity.')
add('E02','E Input handling','High','AI markdown renders unsanitized HTML','frontend/src/lib/markdown.ts','output.push(`<p>${line}</p>`)','Only code spans/blocks escape HTML; ordinary text passes raw HTML to dangerouslySetInnerHTML in editor previews and copilot.','markdownToHtml(`<img src=x onerror="window.__auditXss=1">`) returns executable markup. Feed equivalent model output to the preview; prompt injection provides an input path. No provider call needed to establish sink.','Use a maintained Markdown parser with raw HTML disabled and sanitize allowed HTML/URLs before rendering or editor insertion.')
add('E03','E Input handling','Medium','Upload work is synchronous and authorized after buffering','backend/src/routes/ingestion.routes.ts',"upload.single('file')",'Multer buffers up to 25MB before membership/role checks. OCR/PDF parsing runs in API with no concurrency/page/pixel budget or request deadline; MIME is client-controlled.','An authenticated outsider can repeatedly upload 25MB before receiving 403; authorized compressed image/PDF workloads can exhaust CPU/RAM.','Authorize before multipart parsing; verify file signatures and dimensions; queue bounded isolated parsing with deadlines and rate limits.')
add('E04','E Input handling','Medium','Payload validation leaves broad unbounded content surfaces','backend/src/controllers/document.controller.ts','content: z.any()','Document JSON has no node/depth schema; AI body has only truthiness checks; socket tasks/cursors are any; 10MB HTTP JSON and ws default limits are large relative to workloads.','Submit object prompt or malformed TipTap content, or large arbitrary cursor/task graphs; no domain schema rejects them before downstream use.','Add bounded domain schemas for body/params/query and each event; explicit message/document size, rate and nesting limits.')
add('F01','F AI','High','AI quota is neither accurate nor atomic','backend/src/middleware/billing.middleware.ts','res.once','Metering counts prompt/context characters only after HTTP success, excluding output tokens and retrieved context. Concurrent requests all pass preflight; a streaming error still ends with HTTP 200. Quotas disabled without Stripe configuration; agents bypass metering.','Compare max_tokens=1024 to Math.ceil(input.length/4); send parallel requests near limit. Source confirms no reservation and no provider usage accounting.','Reserve a bounded token budget atomically, settle real provider usage including agents/retrieval, enforce tenant/user concurrency and retry usage reporting durably.')
add('F02','F AI','Medium','Public completion bypasses configured AI gateway','backend/src/controllers/ai.controller.ts','const stream = await groq','Interactive SSE calls Groq directly, with no application deadline, disconnect cancellation or fallback. The timeout/circuit-breaker gateway is used only by task agent.','Stall a provider stream or disconnect the browser: no AbortController/request close handler exists. SDK defaults may time out; no claim of infinite SDK timeout.','Use a shared streaming gateway with explicit deadlines, cancellation, safe error frames, retries and documented fallback semantics.')
add('F03','F AI','Medium','Retrieved content can inject instructions and include archived documents','backend/src/services/embedding.service.ts','FROM "Document" d WHERE','Retrieval filters workspace correctly but omits isArchived=false. Document/PR content is supplied as user instructions without untrusted-context boundaries. No demonstrated cross-workspace RAG query leak.','Archive an embedded document then query its topic; SQL still selects it. Seed content instructing output HTML to exercise E02 through AI. Model obedience remains unverified.','Filter archived/deleted content, minimize context and delimit untrusted evidence; prevent content from becoming executable HTML; document provider data handling.')
add('G01','G Reliability and data','High','RLS context is missing from most protected-table operations','backend/prisma/migrations/20260815000000_phase_3_tenant_rls/migration.sql','FORCE ROW LEVEL SECURITY','Only selected document/snippet list/create and task agent operations set tenant context. Document access checks, update/delete, Yjs persistence, most tasks, search, webhooks and embedding worker use the unscoped client. Supplied postgres credentials bypass RLS, concealing defects.','Run production queries as a NOSUPERUSER NOBYPASSRLS role: direct protected-table reads see no rows/writes fail. Run as Compose postgres: RLS is bypassed. Existing RLS tests construct separate tables and do not test controllers.','Make tenant-bound transactions mandatory end-to-end and supply least-privilege DB roles; integration-test all matrix paths against actual migrations.')
add('G02','G Reliability and data','High','Migrations cannot bootstrap a fresh database','backend/prisma/migrations/20260729180000_enterprise_platform/migration.sql','ALTER TABLE "User"','First migration alters existing tables but no baseline creates User/Workspace/Document/etc. clerkId is nullable in SQL but required in schema. README uses db push, omitting SQL RLS policies and indexes.','On empty PostgreSQL with vector installed, first ALTER TABLE User fails. Existing databases also need explicit identity backfill/NOT NULL handling before auth migration.','Create and validate historical baseline and backfill path; use migrate deploy with a dedicated migration role; test empty and upgrade databases.')
add('G03','G Reliability and data','High','Redis outage blocks purported graceful fallback','backend/src/lib/redis.ts','maxRetriesPerRequest: null','isRedisAvailable awaits ping with unlimited reconnect/offline command retries. Cache get/del likewise await redis commands. Outage can hang snippet reads, joins, adapters and task moves instead of returning false.','Stop Redis then await isRedisAvailable or a cache read: no command timeout or bounded retry is configured. Runtime log shows repeated ECONNREFUSED.','Separate queue and request clients; use fail-fast request commands, bounded health checks, circuit breaker and tested fallback.')
add('G04','G Reliability and data','High','Embedding producer and dedicated worker use different queues','backend/src/services/embedding.service.ts','INSERT INTO "EmbeddingJob"','queueEmbedding writes PostgreSQL EmbeddingJob; worker.ts listens to BullMQ devsync-embedding and never drains that table. API polling is opt-in only.','Create a resource then run npm run worker: no BullMQ embedding job is enqueued. Verify table backlog and absent embedding.','Use one durable producer/consumer mechanism with transactional outbox and acknowledged retries.')
add('G05','G Reliability and data','Medium','Embedding polling races and loses failed work','backend/src/services/embedding.service.ts','const jobs = await','Polling SELECT and processing UPDATE are not atomic across replicas; crashed processing rows are never reclaimed. embed catches failures and returns null, refresh returns success, and job is deleted. Requeued concurrent edits can be deleted by older work.','Two API replicas with RUN_EMBEDDING_WORKER_IN_API=true select the same pending row. Provider failure returns null then DELETE executes.','Claim with SKIP LOCKED/lease and version; retry provider errors, reclaim leases and preserve newer content revisions.')
add('G06','G Reliability and data','High','Yjs state and JSON projections diverge','backend/src/services/yjs.service.ts','data: { yjsState:','CRDT stores update only yjsState, while embeddings/search/agents use content JSON. REST and agent JSON updates do not modify Yjs; editor imports JSON only when yjsState absent.','Edit a persisted Yjs document, inspect content/search: old JSON remains. Append agent summary after yjsState exists: client ignores new JSON.','Choose canonical Yjs state and transactionally derive JSON/indexing; apply server edits through CRDT, with deterministic legacy migration.')
add('G07','G Reliability and data','Medium','Kanban move and position allocation race','backend/src/controllers/task.controller.ts','// Update positions of other tasks','Move increments target tasks then updates moving task in separate operations, never closes source gap. Creation uses max+1 without serialization/unique constraint. Summary append also read-modify-writes JSON concurrently.','Concurrent creates/moves can duplicate positions; error between increment and task update leaves partial mutation. Two summary jobs can overwrite appends.','Use ordered transactional mutations with version/locking or order keys; serialize summary append or use append-only records.')
add('G08','G Reliability and data','High','GitHub task transition crosses workspace boundary','backend/src/routes/github-webhook.routes.ts','const tasks = await prisma.task.findMany','Signed repository event searches globally unique taskKey without filtering owning workspace then moves all matches into the repository workspace.','Repository A PR references a known DEV-123 from B; under supplied bypass-RLS DB, matching B task moves to A. Strict RLS instead yields no rows (G01).','Filter task through column.board.workspaceId and enforce immutable tenant ownership; transactionally validate source and target.')
add('G09','G Reliability and data','High','Webhook delivery is acknowledged before business effects','backend/src/routes/github-webhook.routes.ts','const idempotent = await','Idempotency wrapper covers inserting delivery record only; completed marker is set before processing/enqueue/move. Later failures are suppressed as duplicate on redelivery. Stripe has signature validation but no event ledger/order guard.','Force failure after GitHubWebhookDelivery insert, redeliver same delivery: 202 duplicate, work never retried. Older Stripe checkout completion can overwrite canceled status.','Persist incoming delivery and outbox atomically; process/retry durable state, mark done only after effects; deduplicate/order Stripe events.')
add('G10','G Reliability and data','Medium','Persistence errors are swallowed after CRDT update acknowledgement','backend/src/services/yjs.service.ts','Failed to persist document','Yjs store catches DB errors and resolves normally, making failed persistence appear successful. Debounce also leaves 3–10 seconds of acknowledged in-memory edits at risk on abrupt restart.','Make database unavailable during store, observe error log but no rejected store/retry signal. Kill API before debounce expires.','Propagate failed stores for retry, expose durable acknowledgements, journal updates before confirming durability and test crash recovery.')
add('G11','G Reliability and data','Medium','Fire-and-forget embedding promises can reject unhandled','backend/src/controllers/document.controller.ts',"queueEmbedding('document', document.id)",'Async queueEmbedding calls after res.json are neither awaited nor caught; controller catch cannot catch later rejection. Similar calls exist in snippets/tasks/ingestion.','Cause EmbeddingJob INSERT failure after successful create/update; rejected promise has no handler and can terminate Node.','Persist outbox in mutation transaction or explicitly catch and durably retry failures.')
add('G12','G Reliability and data','Medium','Missing relation indexes and unbounded lists amplify load','backend/prisma/schema.prisma','model Document {','Document workspaceId/parentId, Board workspaceId, Column boardId, Task columnId, Snippet workspaceId and Activity workspaceId/createdAt lack ordinary query indexes. Lists return full documents/code/boards/tasks without pagination; PostgreSQL does not automatically index referencing FKs.','Inspect schema plus SQL migrations: vector indexes exist, most FK/list indexes do not. Seed a large workspace and EXPLAIN representative queries to quantify (unverified performance).','Add measured composite indexes, cursor pagination, projections and payload budgets; avoid broad nested list includes.')
add('B01','B Collaboration','High','Local-first Kanban is a last-writer-wins JSON snapshot with no retry','frontend/src/app/(dashboard)/workspace/[id]/kanban/page.tsx','localBoards.set(data)','Boards use one Y.Map string value containing the entire board, so concurrent edits to different tasks replace each other. Failed REST mutations show a promise of retry, but no outbox/replay exists. Server persists only document rooms, not kanban rooms.','Go offline, add task, reconnect/reload: only local snapshot exists and loadBoards overwrites with server data. Two clients set record:boards/value concurrently: Yjs resolves one whole JSON value.','Model per-task CRDT entries or keep server versioned operations with durable mutation outbox; reconcile optimistic IDs and rollback rejected writes.')
add('B02','B Collaboration','High','Kanban load effect can fetch indefinitely','frontend/src/app/(dashboard)/workspace/[id]/kanban/page.tsx','}, [id, localBoards]);','localBoards changes identity whenever its observed value changes; loadBoards depends on it and effect calls loadBoards, which writes localBoards again.','Load endpoint returns JSON; localBoards.set triggers observer/React value update, recreates callback, retriggers effect. Browser confirmation blocked by authenticated fixture.','Stabilize write callbacks and separate initial fetch from observers; version sync and test that idle board emits bounded requests.')
add('B03','B Collaboration','Medium','Document rehydration can overwrite offline edits','frontend/src/app/(dashboard)/workspace/[id]/docs/[docId]/page.tsx','editor.commands.setContent(doc.content)','Legacy JSON initialization is not coordinated with IndexedDB and remote sync; no atomic migration marker. Multiple clients importing legacy state can duplicate or replace content.','Existing local Yjs edits plus API doc.content with empty yjsState cause setContent on metadata load. Two first clients importing JSON create distinct CRDT structures.','Initialize legacy CRDT server-side once; wait for local/remote sync and never replace populated local state.')
add('B04','B Collaboration','Medium','Collaboration memory and rooms have no application quotas','backend/src/socket/rate-limiter.ts','socketBuckets.set(eventName','Arbitrary event names allocate buckets indefinitely per socket; room joins have rate but no total count cap; empty fallback presence maps are retained. Hocuspocus accepts arbitrary nonexistent IDs and no document-size/room-count quotas.','Send unique event names or many room joins over time; disconnect clears buckets/socket mapping but not empty workspace maps. 10+ editor capacity is unmeasured.','Allowlist event names, cap rooms/update sizes/state, prune empty maps and load-test bounded memory/reconnect behavior.')
add('B05','B Collaboration','Medium','Presence is incorrect across tabs and reconnects','backend/src/socket/presence.handler.ts','const PRESENCE_TTL = 300','Presence keyed by user stores one socket; closing one tab deletes another live tab. TTL refresh occurs only on join; idle live users expire. Client expects userId/userName but server emits id/name; only overview joins workspace and reconnect does not rejoin explicitly.','Open two tabs, close one; inspect hash entry. Wait >300s with no join. View presence bar initials (uses absent userName).','Track per-socket presence with heartbeat and aggregation, consistent DTOs, centralized route membership and reconnect rejoin.')
add('H01','H Frontend','Medium','SSE parsers drop split network frames','frontend/src/components/ai-copilot-drawer.tsx','const lines = chunk.split','Each network chunk is parsed independently; JSON split across reads is caught and discarded. Decoder is not used with streaming mode; SSE error frames ignored. Same parser repeated in editor/snippets.','Split data: {"content":"hello"} across two fetch reader chunks: neither fragment parses.','Use one buffered incremental UTF-8/SSE parser shared by all consumers with error/cancel support.')
add('H02','H Frontend','Medium','Local cache survives logout and is not scoped by user','frontend/src/lib/local-first-yjs.ts','new IndexeddbPersistence','IndexedDB key contains room only, not user identity; signOut does not destroy/delete cached documents. Another account on shared browser can access stale data locally. Copilot/command palette also retain state across workspace navigation.','Sign out then sign in as another user in same origin/browser; inspect devsync:room IndexedDB. No logout cache removal in AuthProvider.','Isolate encrypted local stores by account, define logout retention policy and clear/invalidate sensitive view state on identity/workspace changes.')
add('H03','H Frontend','Medium','Authentication token callbacks destabilize socket lifecycle','frontend/src/providers/auth-provider.tsx','getToken: async () =>','Auth value recreates getToken on user/auth memo changes. SocketProvider depends on it and lacks disposed guard around pending token promise. Local-first hook captures one token string, with no refresh callback.','Unmount before getToken resolves: SocketProvider can create an orphan socket. Expired token reconnect reuses captured token.','Use stable callbacks, disposed guards and provider-supported token refresh; destroy Y.Doc instances and reset stores on room changes.')
add('H04','H Frontend','Medium','Keyboard access and dialog semantics are missing','frontend/src/app/(dashboard)/workspace/[id]/kanban/page.tsx','<div key={task.id} draggable','Task cards rely on div onClick/native mouse drag, no keyboard move actions/tabIndex; modals lack dialog role, focus trapping, Escape and restoration; icon controls lack names and labels are unassociated.','Keyboard-only navigation cannot focus task card or move it. Dashboard create modal is a generic div (dashboard/page.tsx:132).','Implement accessible buttons/cards, keyboard move menu, labeled form controls and tested dialog primitives. Measure contrast in authenticated UI before asserting ratios.')
